const C1 = '#1a2a4a'; // Deep blue
const C2 = '#3a5a7a'; // Blue-green
const C3 = '#5a7a9a'; // Teal-blue
const C4 = '#7a9abc'; // Light blue
const C5 = '#9acbd0'; // Pale blue
const C6 = '#b0d8e0'; // Very pale blue

// Draw background
ctx.fillStyle = C1;
ctx.fillRect(0, 0, W, H);

// Draw spiral
function drawSpiral(x, y, size, depth) {
    if (depth > 0) {
        // Draw concentric circles
        ctx.fillStyle = C4;
        ctx.beginPath();
        ctx.arc(x, y, size, 0, Math.PI * 2);
        ctx.fill();

        // Draw spiral arms
        ctx.strokeStyle = C5;
        ctx.lineWidth = 2;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(x, y);
        for (let i = 0; i < 8; i++) {
            const angle = (i / 8) * Math.PI * 2;
            const endX = x + Math.cos(angle) * size;
            const endY = y + Math.sin(angle) * size;
            ctx.lineTo(endX, endY);
        }
        ctx.stroke();

        // Recurse with smaller size and deeper depth
        drawSpiral(x + Math.cos(Math.PI/4) * size/2, 
                   y + Math.sin(Math.PI/4) * size/2, 
                   size * 0.8, depth - 1);
    }
}

