// Shell spiral
ctx.strokeStyle = '#8B4513';
ctx.lineWidth = 3;
ctx.beginPath();
ctx.moveTo(200, 250);
for (let i = 0; i < 20; i++) {
    const angle = i * 0.5;
    const radius = 30 + i * 5;
    const x = 200 + Math.cos(angle) * radius;
    const y = 250 + Math.sin(angle) * radius;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
}
ctx.stroke();

// Shell details
ctx.strokeStyle = '#A0522D';
ctx.lineWidth = 1;
for (let i = 0; i < 15; i++) {
    const angle = i * 0.7;
    const radius = 25 + i * 3;
    const x = 200 + Math.cos(angle) * radius;
    const y = 250 + Math.sin(angle) * radius;
    ctx.beginPath();
    ctx.arc(x, y, 3, 0, Math.PI * 2);
    ctx.stroke();
}

